function ProductItem({ product, onSelect }) {
  return <li onClick={() => onSelect(product.id)}>{product.name}</li>;
}

function ProductList({ products, onSelect }) {
  return (
    <ul>
      {products.map((p) => (
        <ProductItem key={p.id} product={p} onSelect={onSelect} />
      ))}
    </ul>
  );
}

function Cart({ items, loading }) {
  if (loading) return <p>Carregando...</p>;
  return (
    <section>
      {items.length > 0 ? <ItemList items={items} /> : <p>Carrinho vazio</p>}
      {items.length > 0 && <CheckoutButton />}
    </section>
  );
}

function Profile({ userId }) {
  const [user, setUser] = useState(null);

  useEffect(() => {
    const controller = new AbortController();
    fetch(`/api/users/${userId}`, { signal: controller.signal })
      .then((r) => r.json())
      .then(setUser)
      .catch(() => {});
    return () => controller.abort();
  }, [userId]);

  return user ? <h1>{user.name}</h1> : <p>Carregando...</p>;
}

function useLocalStorage(key, initial) {
  const [value, setValue] = useState(() => {
    const saved = localStorage.getItem(key);
    return saved !== null ? JSON.parse(saved) : initial;
  });

  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);

  return [value, setValue];
}

